import { useCallback } from 'react';

import { useDatetimeMutator } from '@eventespresso/edtr-services';
import { useTimeZoneTime } from '@eventespresso/services';
import { InlineDateRangeEdit } from '@eventespresso/ui-components';

import type { Datetime } from '@eventespresso/edtr-services';
import type { Datetime as DatetimeType } from '@eventespresso/types';

interface EditableDateTimeProps {
	datetime: Datetime;
	dateField: DatetimeType.DateField;
}

const EditableDateTime: React.FC<EditableDateTimeProps> = ({ datetime, dateField }) => {
	const { updateEntity } = useDatetimeMutator(datetime.id);
	const { siteTimeToUtc } = useTimeZoneTime();

	const onChange = useCallback(
		([startDate, endDate]) => {
			updateEntity({
				id: datetime.id,
				startDate: startDate ? siteTimeToUtc(startDate).toISOString() : null,
				endDate: endDate ? siteTimeToUtc(endDate).toISOString() : null,
			});
		},
		[updateEntity, datetime.id, siteTimeToUtc]
	);

	return (
		<InlineDateRangeEdit
			id={datetime.id}
			date={datetime?.[dateField]}
			startDate={datetime.startDate}
			endDate={datetime.endDate}
			onChange={onChange}
			dateField={dateField}
		/>
	);
};

export default EditableDateTime;
